-- Adds `Project.templateName` (nullable text) for the evocative
-- 2-3 word brand-style name that drives the default title in the
-- "Save copy as template" flow. Generated by a Claude Haiku call
-- during deck-generate completion; null on legacy decks until the
-- backfill script runs.
ALTER TABLE "Project" ADD COLUMN "templateName" TEXT;

-- Also rolls the NOT NULL enforcement on `Project.colorTags` into
-- migration history. The earlier `color_tags_default` migration
-- only set the DEFAULT — the local DB had NOT NULL added via raw
-- SQL after the fact, leaving migration history out of sync with
-- the schema's non-null contract (CR flagged on PR #30; the earlier
-- attempt to edit the previous migration file in place triggered
-- Prisma's drift-protection and was backed out). Placing the
-- backfill + constraint here means a clean DB rebuild lands at the
-- same NOT NULL state as our incrementally-patched live one.
UPDATE "Project" SET "colorTags" = ARRAY[]::TEXT[] WHERE "colorTags" IS NULL;
ALTER TABLE "Project" ALTER COLUMN "colorTags" SET NOT NULL;
